<script setup lang="ts">
import {computed,ref} from 'vue'
import UiButton from '@/components/ui/UiButton.vue'
import UiDialog from '@/components/ui/UiDialog.vue'
import UiSelectField from '@/components/ui/UiSelectField.vue'
import {useAppStore} from '@/stores/app'
import {displayPath} from '@/lib/paths'
import {useRuntimeRecoveryV2Store} from './recovery-v2'
const props=defineProps<{disabled?:boolean}>(),recovery=useRuntimeRecoveryV2Store(),app=useAppStore(),file=ref<HTMLInputElement|null>(null)
const preview=computed(()=>recovery.mode==='operation'?recovery.status?.preview:null)
const phase=computed(()=>recovery.executing&&recovery.status?.phase!=='applying'?'正在等待原恢复操作回执':({prepared:'已准备，尚未恢复',applying:'原恢复正在执行',succeeded:'恢复已成功读回',failed:'恢复未成功完成',cancelled:'已取消，未执行恢复'})[recovery.status?.phase??'prepared'])
const paths=computed(()=>{const p=preview.value;return !p?[]:[['当前程序目录',p.prefix],['当前入口',p.entry],['旧程序保留位置',p.retainedPrefix],['恢复元数据备份',p.metadataBackup],['Desktop 工作根',p.desktopRoot],['选定恢复归档',p.selectedArchive]]})
const canConfirm=computed(()=>recovery.canApply&&!props.disabled)
async function selected(event:Event){const input=event.target as HTMLInputElement,value=input.files?.[0];input.value='';if(value)await recovery.stage(value)}
async function dropped(event:DragEvent){if(recovery.staging||recovery.preparing||props.disabled)return;const value=event.dataTransfer?.files?.[0];if(value)await recovery.stage(value)}
</script>
<template>
 <UiDialog :open="recovery.open" :title="recovery.mode==='prepare'?'诊断与恢复程序':'程序恢复记录'" wide :busy="recovery.staging||recovery.cancelling" panel-class="runtime-recovery-v2" @close="recovery.close()">
  <template v-if="recovery.mode==='prepare'"><p>先检查程序安装与恢复来源，预览实际影响后再确认恢复。</p><div class="recovery-actions"><UiButton :disabled="app.doctorLoading||recovery.preparing" @click="app.loadDoctorReport()">{{app.doctorLoading?'正在诊断':'运行只读诊断'}}</UiButton></div><p v-if="app.doctorError" role="alert" class="model-error">诊断暂不可用，已有结果保持；恢复预览会另行核对程序证据。</p><details v-if="app.doctorReport"><summary>本次只读诊断</summary><pre>{{app.doctorReport.lines.join('\n')}}</pre></details><UiSelectField :model-value="recovery.source" label="程序恢复来源" :disabled="recovery.preparing||recovery.staging||disabled" :options="[{value:'bundled',label:'本版随包程序'},{value:'offline',label:'本版维护恢复包'}]" @update:model-value="recovery.chooseSource($event as 'bundled'|'offline')" /><p v-if="recovery.source==='bundled'">使用本版固定资源与编译校验记录；资源不可用时保留原程序并显示实际错误。</p><div v-else class="recovery-drop" @dragover.prevent @drop.prevent="dropped"><input ref="file" hidden type="file" accept=".tgz,.tar.gz" aria-label="选择维护恢复包" @change="selected" /><UiButton :disabled="recovery.preparing||recovery.staging||disabled" @click="file?.click()">选择本机恢复包</UiButton><p>也可拖入用户选定的本版维护恢复包；来源与摘要由后端核对。</p><p v-if="recovery.staging" role="status">正在读取并校验所选包…</p><p v-if="recovery.offline" role="status">{{recovery.offline.fileName}} · {{recovery.offline.message}} · {{recovery.offline.version??'版本未确认'}}</p></div><p v-if="recovery.preparing" role="status">正在准备只读恢复预览，程序尚未修改。</p></template>
  <template v-else-if="recovery.status&&preview"><p role="status">{{phase}}</p><p>原操作 {{preview.operationId}}</p><dl class="recovery-facts"><dt>包 / 清单 / 来源版本</dt><dd>{{preview.packageVersion??'未记录'}} / {{preview.manifestVersion??'未记录'}} / {{preview.sourceVersion??'未记录'}}</dd><dt>程序一致性</dt><dd>{{preview.consistency==='consistent'?'后端已核对一致':preview.consistency==='mismatchOrCorrupted'?'不一致或存在损坏':preview.consistency}}</dd><dt>本次恢复版本</dt><dd>{{preview.selectedVersion}}</dd><dt>本用户服务归属</dt><dd>{{preview.service.state==='stopped'?'已确认未运行':preview.service.state==='owned'?'已确认本用户拥有的服务；恢复时先停止':'归属未知，不能自动停止'}}</dd><template v-for="[name,path] in paths" :key="name"><dt>{{name}}</dt><dd><code class="local-path">{{displayPath(path)}}</code></dd></template></dl><p v-if="recovery.status.restartRequired" role="status">后端报告需要重启；请核对完成状态后再启动 OpenCodex。</p><p v-if="recovery.status.detail" role="alert" class="model-error">{{recovery.status.detail}}</p><p v-if="recovery.status.phase==='prepared'&&!recovery.executing">确认后将保护当前元数据、停止已证明归属的服务、替换受管程序并读回核验；用户配置按后端保护范围保留。</p><p v-else-if="recovery.executing||recovery.status.phase==='applying'">关闭窗口只停止观察。后台原操作继续，重新打开可读取同一操作状态。</p><UiButton variant="ghost" :disabled="recovery.reading" @click="recovery.read()">读取原操作状态</UiButton><details><summary>来源核对摘要</summary><p>程序树 {{preview.packageTreeSha256}}</p><p>选定归档 {{preview.selectedSha256}}</p><p>入口 {{preview.entrySha256??'无可用入口摘要'}}</p><p>来源记录 {{preview.sourceRecordSha256??'无可用来源摘要'}}</p></details></template>
  <p v-if="recovery.error" role="alert" class="model-error">{{recovery.error}}</p>
  <template v-if="recovery.mode==='prepare'||recovery.status?.phase==='prepared'&&!recovery.executing" #actions="{close}"><UiButton :disabled="recovery.staging||recovery.cancelling" @click="close">取消</UiButton><UiButton v-if="recovery.mode==='prepare'" variant="primary" :disabled="disabled||recovery.preparing||recovery.staging||recovery.source==='offline'&&(!recovery.stagedId||!recovery.offline?.ok)" :loading="recovery.preparing" @click="recovery.prepare()">预览恢复方案</UiButton><UiButton v-else variant="primary" :disabled="!canConfirm" @click="recovery.apply()">确认恢复受管程序</UiButton></template>
 </UiDialog>
</template>
<style scoped>
.recovery-actions{display:flex;gap:var(--space-2);flex-wrap:wrap}.recovery-facts{display:grid;grid-template-columns:150px minmax(0,1fr);gap:var(--space-3)}dt{color:var(--muted)}dd{margin:0;overflow-wrap:anywhere}pre{white-space:pre-wrap;overflow-wrap:anywhere;max-height:280px;overflow:auto}.recovery-drop{border:1px dashed var(--border);border-radius:var(--radius);padding:var(--space-4);margin-block:var(--space-3)}.model-error{color:var(--red)}p{overflow-wrap:anywhere}@media(max-width:620px){.recovery-facts{grid-template-columns:minmax(0,1fr)}}
</style>
